int def scoreCapital(double:actualCapital, double:registeredCapital) {
    if (registeredCapital == 0){
       return 0;
    }
    double ratio = actualCapital / registeredCapital;
    if (ratio >= 1.0) {
        return 8;
    } else if (ratio >= 0.5) {
        return 5;
    } else if (ratio >= 0.2) {
        return 3;
    } else {
        return 0;
    }
}


int def scoreEstablishment(int:years) {
    if (years >= 10) {
        return 6;
    } else if (years >= 5) {
        return 4;
    } else if (years >= 3) {
        return 2;
    } else {
        return 0;
    }
}


