double def calculateTotalScore(int:basicScore,int:financialScore,int:performanceScore,int:managementScore,int:complianceScore) {
    // 维度满分: 基本资质20, 财务30, 履约25, 管理15, 合规10
    double expectedTotal = basicScore;
    double financialScoreTotal= financialScore;
    double performanceScoreTotal= performanceScore;
    double managementScoreTotal= managementScore;
    double complianceScoreTotal= complianceScore;
    return expectedTotal + financialScoreTotal + performanceScoreTotal + managementScoreTotal + complianceScoreTotal;
 }
